<script setup>
import { ref, watch } from 'vue'; import MButton from '../../../components/mds/MButton.vue'; import MEmptyState from '../../../components/mds/MEmptyState.vue'; import MInput from '../../../components/mds/MInput.vue'; import MMobileTopBar from '../../../components/mds/MMobileTopBar.vue'; import MTag from '../../../components/mds/MTag.vue'; const props = defineProps({ rows:{type:Array,default:()=>[]},total:Number,page:Number,pageSize:Number,search:String,loading:Boolean,canCreate:Boolean,canIntake:Boolean,safeAreaStyle:Object }); const emit=defineEmits(['back','search','page','create','intake','open']); const query=ref(props.search||''); watch(()=>props.search,(v)=>{query.value=v||'';});
</script>
<template><section class="mds-mobile-app flex h-[100dvh] min-w-0 flex-col overflow-hidden bg-[var(--mds-bg)]" :style="safeAreaStyle"><MMobileTopBar title="Sự kiện" @back="emit('back')"><template #actions><MButton v-if="canIntake" variant="link" @click="emit('intake')">AI</MButton><MButton v-if="canCreate" variant="link" @click="emit('create')">Thêm</MButton></template></MMobileTopBar><form class="mds-mobile-gutter-x flex gap-2 border-b border-[var(--mds-border-light)] py-3" @submit.prevent="emit('search',query.trim())"><MInput v-model="query" placeholder="Tìm sự kiện…"/><MButton variant="primary" :loading="loading" @click="emit('search',query.trim())">Tìm</MButton></form><div class="min-h-0 flex-1 overflow-y-auto"><div v-if="rows.length" class="divide-y divide-[var(--mds-border-light)]"><button v-for="row in rows" :key="row.id" type="button" class="mds-mobile-gutter-x block min-h-16 w-full py-3 text-left" @click="emit('open', row.id)"><div class="flex items-start justify-between gap-3"><strong class="min-w-0 text-[14px] leading-5">{{ row.name }}</strong><MTag color="neutral">{{ row.status||'—' }}</MTag></div><p class="mt-1 text-[13px] text-[var(--mds-text-secondary)]">{{ row.start_time||'Chưa có thời gian' }} · {{ row.organizer||row.org_name||'—' }}</p></button></div><MEmptyState v-else-if="!loading" title="Chưa có sự kiện" description="Sự kiện được phép xem sẽ xuất hiện tại đây."/><div v-else class="p-6 text-center text-[13px]">Đang tải sự kiện…</div></div><footer class="flex shrink-0 justify-between border-t border-[var(--mds-border-light)] px-4 pb-[calc(12px+var(--mds-mobile-safe-bottom))] pt-3"><MButton variant="neutral" :disabled="loading||page<=1" @click="emit('page',page-1)">Trước</MButton><span class="self-center text-[12px]">{{ total||0 }} mục</span><MButton variant="neutral" :disabled="loading||page*pageSize>=total" @click="emit('page',page+1)">Sau</MButton></footer></section></template>
